+/**
+ * Pack the self-contained MCP App HTML into a small, still self-contained
+ * bootstrap. MCP hosts transport resources/read as JSON, where a large inline
+ * React bundle is counted after decompression and escaping. Keeping the gzip
+ * payload inside the HTML avoids host response-size ceilings without adding a
+ * network dependency: the iframe expands it with the browser-native
+ * DecompressionStream API, then replaces the bootstrap document with the
+ * original application document.
+ */
+import { readFile, writeFile } from "node:fs/promises";
+import { gzipSync } from "node:zlib";
+
+const bundleUrl = new URL(
+	"../dist-mcp-apps/interaction/index.html",
+	import.meta.url,
+);
+const source = await readFile(bundleUrl, "utf8");
+
+if (source.includes('name="lobu-mcp-packing"')) {
+	throw new Error("MCP App bundle is already packed");
+}
+
+const payload = gzipSync(Buffer.from(source, "utf8"), { level: 9 }).toString(
+	"base64",
+);
+const packed = `<!doctype html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width,initial-scale=1">
+<meta name="lobu-mcp-packing" content="gzip-base64-v1">
+<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; connect-src 'none'; font-src 'none'; media-src 'none'; object-src 'none'; frame-src 'none'; base-uri 'none'; form-action 'none'">
+<title>Lobu</title>
+</head>
+<body><p id="lobu-mcp-loading" role="status">Loading Lobu…</p>
+<script id="lobu-mcp-payload" type="application/gzip">${payload}</script>
+<script>
+(async()=>{
+  const loading=document.getElementById("lobu-mcp-loading");
+  try {
+    if(typeof DecompressionStream!=="function") throw new Error("This host does not support compressed MCP Apps");
+    const encoded=document.getElementById("lobu-mcp-payload").textContent.trim();
+    const binary=atob(encoded);
+    const bytes=Uint8Array.from(binary,character=>character.charCodeAt(0));
+    const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
+    const html=await new Response(stream).text();
+    document.open();
+    document.write(html);
+    document.close();
+  } catch(error) {
+    loading.textContent="Unable to load Lobu.";
+    console.error("[mcp-app] failed to unpack",error);
+  }
+})();
+</script></body></html>`;
+
+await writeFile(bundleUrl, packed, "utf8");
+console.log(
+	`Packed MCP App bundle (${Buffer.byteLength(source).toLocaleString()} → ${Buffer.byteLength(packed).toLocaleString()} HTML bytes).`,
+);
